def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=False, **kwargs):
    if orjson is None or force_use_builtin_json:
        if force_use_builtin_json and orjson is not None and 'sort_keys' in kwargs:
            raise TypeError('orjson does not accept the sort_keys parameter. Please pass force_use_builtin_json=True to use the builtin json library.')
        return json.dumps(item, default=json_convertor_default(default_mapping), **kwargs)
